import { spawnSync } from "node:child_process";
import { mkdir, mkdtemp, readFile, rename, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

import openapiTS, { astToString } from "openapi-typescript";

const GENERATED_HEADER = `/**
 * Generated from Numismat's canonical offline FastAPI OpenAPI contract.
 * Run \`npm run api:generate\`; do not edit this file manually.
 */

`;

const webRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const repositoryRoot = resolve(webRoot, "..");
const targetPath = join(webRoot, "src", "api", "generated", "schema.ts");
const isCheck = process.argv.slice(2).includes("--check");

function exportOpenApi(schemaPath) {
  const executable = process.env.NUMISMAT_UV_EXECUTABLE ?? "uv";
  const result = spawnSync(
    executable,
    ["run", "--frozen", "python", "scripts/export_openapi.py", "--output", schemaPath],
    {
      cwd: repositoryRoot,
      env: process.env,
      stdio: "inherit",
      windowsHide: true,
    },
  );

  if (result.error) {
    throw new Error("The canonical OpenAPI exporter could not be started", {
      cause: result.error,
    });
  }
  if (result.status !== 0) {
    throw new Error("The canonical OpenAPI exporter failed");
  }
}

function canonicalize(value) {
  return value.replaceAll("\r\n", "\n").replaceAll("\r", "\n").trimEnd() + "\n";
}

async function renderTypes(schemaPath) {
  const ast = await openapiTS(pathToFileURL(schemaPath), { silent: true });
  return canonicalize(GENERATED_HEADER + astToString(ast));
}

async function writeAtomically(content) {
  const temporaryPath = `${targetPath}.${process.pid}.tmp`;
  await mkdir(dirname(targetPath), { recursive: true });
  await writeFile(temporaryPath, content, { encoding: "utf8", mode: 0o600 });
  try {
    await rename(temporaryPath, targetPath);
  } finally {
    await rm(temporaryPath, { force: true });
  }
}

async function checkGenerated(expected) {
  let actual;
  try {
    actual = canonicalize(await readFile(targetPath, "utf8"));
  } catch (error) {
    if (error instanceof Error && "code" in error && error.code === "ENOENT") {
      throw new Error("Generated API types are missing; run npm run api:generate");
    }
    throw error;
  }

  if (actual !== expected) {
    throw new Error("Generated API types drifted; run npm run api:generate");
  }
}

const temporaryDirectory = await mkdtemp(join(tmpdir(), "numismat-openapi-"));
try {
  const schemaPath = join(temporaryDirectory, "numismat-v1.json");
  exportOpenApi(schemaPath);
  const generated = await renderTypes(schemaPath);

  if (isCheck) {
    await checkGenerated(generated);
    process.stdout.write("[api-types] contract is current\n");
  } else {
    await writeAtomically(generated);
    process.stdout.write("[api-types] generated\n");
  }
} finally {
  await rm(temporaryDirectory, { recursive: true, force: true });
}
